#include <Aevrynd/Scene3D.h>
#include <chrono>
#include <cstdint>
#include <iostream>

using namespace Aevrynd;

int main(){
    Scene3D scene;for(int z=-40;z<=40;++z)for(int x=-40;x<=40;++x){const float height=1.f+float((x*x+z*z)%5)*.4f;scene.Box({float(x)*2.5f,height*.5f,float(z)*2.5f},{1.5f,height,1.5f},{.2f,.7f,.8f,1});}
    Camera3D camera=MakeIsometricCamera({0,1,0},48,32);constexpr Vec2 Viewport{1280,720};constexpr int Iterations=120;DrawList culledDraw,fullDraw;
    // 先建立兩種路徑的容量，避免容器首次配置扭曲裁切成本比較。
    Scene3DStats culledStats=scene.Submit(culledDraw,camera,Viewport);Scene3DStats fullStats=scene.Submit(fullDraw,camera,Viewport,{false});culledDraw.Clear();fullDraw.Clear();
    auto measure=[&](DrawList& draw,Scene3DSubmissionOptions options){const auto start=std::chrono::steady_clock::now();for(int index=0;index<Iterations;++index){draw.Clear();scene.Submit(draw,camera,Viewport,options);}return uint64_t(std::chrono::duration_cast<std::chrono::microseconds>(std::chrono::steady_clock::now()-start).count())/Iterations;};
    const uint64_t culledAverageUs=measure(culledDraw,{}),fullAverageUs=measure(fullDraw,{false});auto boxCpu=std::make_shared<Mesh3D>(Mesh3D::CreateUnitBox());scene.SetBoxMesh({{1},boxCpu->Bounds(),boxCpu->vertices.size(),boxCpu->indices.size(),boxCpu});DrawList instancedDraw;Scene3DStats instancedStats=scene.Submit(instancedDraw,camera,Viewport);instancedDraw.Clear();const uint64_t instancedAverageUs=measure(instancedDraw,{});
    const uint64_t culledBytes=culledDraw.worldVertices.size()*sizeof(Vertex3D)+culledDraw.worldIndices.size()*sizeof(uint32_t),fullBytes=fullDraw.worldVertices.size()*sizeof(Vertex3D)+fullDraw.worldIndices.size()*sizeof(uint32_t),reductionPermille=fullBytes?(fullBytes-culledBytes)*1000/fullBytes:0;
    const uint64_t instancedBytes=instancedDraw.meshInstances.size()*D3D12Renderer::MeshInstanceUploadBytes,instanceReductionPermille=culledBytes?(culledBytes-instancedBytes)*1000/culledBytes:0;
    constexpr int QueryCount=240;SceneQueryStats3D totalQueryStats{};std::size_t queryHits{};const auto queryStart=std::chrono::steady_clock::now();for(int index=0;index<QueryCount;++index){const int x=index%31-15,z=index/31-4;SceneQueryStats3D queryStats{};const SceneHit3D hit=scene.Raycast({{float(x)*2.5f,50,float(z)*2.5f},{0,-1,0}},100,&queryStats);queryHits+=bool(hit);totalQueryStats.boundsTested+=queryStats.boundsTested;totalQueryStats.boundsRejected+=queryStats.boundsRejected;totalQueryStats.trianglesTested+=queryStats.trianglesTested;}const uint64_t queryAverageUs=uint64_t(std::chrono::duration_cast<std::chrono::microseconds>(std::chrono::steady_clock::now()-queryStart).count())/QueryCount,queryRejectPermille=totalQueryStats.boundsTested?totalQueryStats.boundsRejected*1000/totalQueryStats.boundsTested:0;
    auto highCpu=std::make_shared<Mesh3D>(Mesh3D::CreateUnitSphere(12,8)),lowCpu=std::make_shared<Mesh3D>(Mesh3D::CreateUnitSphere(6,3));const MeshResource3D highLod{{11},highCpu->Bounds(),highCpu->vertices.size(),highCpu->indices.size(),highCpu},lowLod{{12},lowCpu->Bounds(),lowCpu->vertices.size(),lowCpu->indices.size(),lowCpu};Scene3D lodScene;for(int z=-30;z<=30;++z)for(int x=-30;x<=30;++x)lodScene.MeshLod(highLod,lowLod,60,{{float(x)*2.5f,1,float(z)*2.5f},{},{1.5f,1.5f,1.5f}});DrawList lodDraw;const Scene3DStats lodStats=lodScene.Submit(lodDraw,camera,Viewport);const auto lodStart=std::chrono::steady_clock::now();for(int index=0;index<Iterations;++index){lodDraw.Clear();lodScene.Submit(lodDraw,camera,Viewport);}const uint64_t lodAverageUs=uint64_t(std::chrono::duration_cast<std::chrono::microseconds>(std::chrono::steady_clock::now()-lodStart).count())/Iterations;
    constexpr Scene3DSubmissionOptions ShadowOptions{true,true,{true,.025f,.2f,100.f,512}};DrawList shadowDraw;const Scene3DStats shadowStats=lodScene.Submit(shadowDraw,camera,Viewport,ShadowOptions);const auto shadowStart=std::chrono::steady_clock::now();for(int index=0;index<Iterations;++index){shadowDraw.Clear();lodScene.Submit(shadowDraw,camera,Viewport,ShadowOptions);}const uint64_t shadowAverageUs=uint64_t(std::chrono::duration_cast<std::chrono::microseconds>(std::chrono::steady_clock::now()-shadowStart).count())/Iterations;const std::size_t overlayInstances=std::count_if(shadowDraw.meshInstances.begin(),shadowDraw.meshInstances.end(),[](const MeshInstance3D& instance){return instance.layer==MeshRenderLayer3D::Overlay;});
    std::cout<<"input="<<culledStats.meshInstances<<" visible="<<culledStats.visibleMeshInstances<<" culled="<<culledStats.culledMeshInstances<<" culledBytes="<<culledBytes<<" fullBytes="<<fullBytes<<" reductionPermille="<<reductionPermille<<" instancedBytes="<<instancedBytes<<" instanceReductionPermille="<<instanceReductionPermille<<" instancedAverageUs="<<instancedAverageUs<<" expandedAverageUs="<<culledAverageUs<<" fullAverageUs="<<fullAverageUs<<" lodNear="<<lodStats.nearLodInstances<<" lodFar="<<lodStats.farLodInstances<<" lodSaved="<<lodStats.lodTrianglesSaved<<" lodAverageUs="<<lodAverageUs<<" shadowCasters="<<shadowStats.shadowCasters<<" shadows="<<shadowStats.shadowInstances<<" shadowSkipped="<<shadowStats.shadowSkipped<<" shadowAverageUs="<<shadowAverageUs<<" queryHits="<<queryHits<<" queryBounds="<<totalQueryStats.boundsTested<<" queryRejected="<<totalQueryStats.boundsRejected<<" queryRejectPermille="<<queryRejectPermille<<" queryTriangles="<<totalQueryStats.trianglesTested<<" queryAverageUs="<<queryAverageUs<<'\n';
    if(culledStats.meshInstances!=6561||culledStats.visibleMeshInstances==0||culledStats.culledMeshInstances==0||fullStats.visibleMeshInstances!=6561||culledBytes>=fullBytes||reductionPermille<800||instancedStats.visibleMeshInstances!=culledStats.visibleMeshInstances||instancedDraw.meshInstances.size()!=culledStats.visibleMeshInstances||!instancedDraw.worldVertices.empty()||instancedBytes>=culledBytes||instanceReductionPermille<800||!lodStats.nearLodInstances||!lodStats.farLodInstances||!lodStats.lodTrianglesSaved||lodAverageUs>3000||shadowStats.shadowInstances!=512||overlayInstances!=shadowStats.shadowInstances||shadowDraw.meshInstances.size()!=shadowStats.visibleMeshInstances+shadowStats.shadowInstances||shadowAverageUs>4000||queryHits!=QueryCount||queryRejectPermille<990||totalQueryStats.trianglesTested>QueryCount*24||queryAverageUs>500)return 1;
    return 0;
}
